export const faqs:Record<Locale,[string,string][]>= {
 en:[["What is a Superbuy spreadsheet?","An independent directory of product links grouped by category. It helps with discovery; the current product page remains the source of truth for price, options and availability."],["What does Superbuy officially provide at the warehouse?","Superbuy's User Guidance describes warehouse inspection, photos for review and 90 days of free storage. Its current fee page lists detailed photos and re-inspection as optional paid services, so ask for a targeted view when the standard evidence cannot answer a specific question."],["Are the displayed prices final?","No. USD amounts are browsing references. Check the exact live variant price, China domestic delivery, any purchasing fee that applies to the source platform, optional services and international parcel cost before ordering."],["How is international shipping charged?","Superbuy says the deposit estimate depends on destination, selected line and estimated parcel data. The logistics provider's verified size and weight determine the final charge; overpayment is refunded or an underpayment may be collected after reconciliation."],["Is ordinary purchasing always fee-free?","Superbuy currently lists standard purchasing from Taobao, Tmall, JD.com and 1688 as free of purchasing service fees. Second-hand, unlisted and special purchasing services can use flat or percentage fees, so check the live fee structure for the exact source."],["Does 90-day free storage mean a 90-day return window?","No. Warehouse storage and seller after-sales are separate clocks. Superbuy's current fee page says storage charges begin after the free period and gives a maximum storage policy; return eligibility depends on the order, seller, item type and live after-sales status."],["Can every warehouse item use every shipping line?","No. Superbuy says some items are restricted to certain delivery methods. Route eligibility depends on destination, item classification and current carrier rules, so confirm batteries, liquids, powders, magnets and other sensitive goods before buying when the route is critical."],["Is this the official Superbuy website?","No. This is an independent informational product directory and is not affiliated with or endorsed by Superbuy."]],
 de:[["Was ist eine Superbuy-Tabelle?","Ein unabhängiges, nach Kategorien sortiertes Verzeichnis von Produktlinks. Es erleichtert die Suche; für Preis, Varianten und Verfügbarkeit zählt die aktuelle Produktseite."],["Was bietet Superbuy offiziell im Lager?","Die Nutzeranleitung nennt Lagerprüfung, Fotos zur Kontrolle und 90 Tage kostenlose Lagerung. Detailfotos und Nachprüfung stehen in der aktuellen Gebührenübersicht als optionale Leistungen; bei einer konkreten Unsicherheit sollte die Anfrage deshalb gezielt sein."],["Sind die angezeigten Preise endgültig?","Nein. USD-Beträge dienen nur zur Orientierung. Prüfe die exakte Live-Variante, Inlandversand, mögliche plattformabhängige Einkaufsgebühren, Zusatzleistungen und internationale Fracht."],["Wie werden internationale Versandkosten berechnet?","Die Vorauszahlung hängt laut Superbuy von Ziel, Linie und geschätzten Paketdaten ab. Bestätigte Maße und Gewicht bestimmen den Endpreis; Überzahlungen werden erstattet, Unterzahlungen können nachberechnet werden."],["Ist der normale Einkauf immer gebührenfrei?","Superbuy nennt den Standardkauf bei Taobao, Tmall, JD.com und 1688 derzeit gebührenfrei. Für Secondhand-, nicht gelistete oder besondere Einkaufsdienste können Pauschalen oder Prozentgebühren gelten."],["Sind 90 Tage Lagerung zugleich 90 Tage Rückgaberecht?","Nein. Lagerfrist und Verkäufer-Nachverkauf sind getrennt. Nach der kostenlosen Lagerzeit können Lagerkosten entstehen; Rückgabe hängt vom Auftrag, Verkäufer, Produkttyp und aktuellen After-Sales-Status ab."],["Kann jeder Lagerartikel über jede Linie versendet werden?","Nein. Laut Superbuy sind manche Artikel auf bestimmte Versandarten beschränkt. Ziel, Warenklassifizierung und aktuelle Carrier-Regeln entscheiden; sensible Waren sollten vor dem Kauf geprüft werden."],["Ist dies die offizielle Superbuy-Website?","Nein. Dies ist ein unabhängiges Informations- und Produktverzeichnis ohne Verbindung oder Empfehlung durch Superbuy."]],
 fr:[["Qu'est-ce qu'un tableur Superbuy ?","Un répertoire indépendant de liens produits classés par catégorie. Il facilite la découverte ; la page produit actuelle reste la référence pour le prix, les options et la disponibilité."],["Que fournit officiellement Superbuy à l'entrepôt ?","Le guide officiel décrit l'inspection, les photos de contrôle et 90 jours de stockage gratuit. La grille actuelle présente les photos détaillées et la réinspection comme services optionnels : demandez une preuve ciblée si un point reste incertain."],["Les prix affichés sont-ils définitifs ?","Non. Les montants USD sont indicatifs. Vérifiez la variante active, la livraison chinoise, les éventuels frais liés à la plateforme, les services choisis et le transport international."],["Comment le transport international est-il facturé ?","L'acompte dépend de la destination, de la ligne et des données estimées. Le poids et les dimensions vérifiés fixent le total ; un trop-perçu est remboursé et un solde insuffisant peut être réclamé."],["L'achat standard est-il toujours sans frais ?","Superbuy indique actuellement zéro frais d'achat standard pour Taobao, Tmall, JD.com et 1688. Les achats d'occasion, plateformes non listées ou services spéciaux peuvent être facturés différemment."],["Les 90 jours de stockage sont-ils un délai de retour ?","Non. Stockage et après-vente du vendeur suivent deux délais distincts. Des frais peuvent commencer après la période gratuite ; l'éligibilité au retour dépend de la commande et du statut après-vente actif."],["Tous les articles peuvent-ils utiliser toutes les lignes ?","Non. Certains articles sont limités à certaines méthodes. Destination, classification et règles actuelles du transporteur comptent ; vérifiez les produits sensibles avant achat."],["S'agit-il du site officiel Superbuy ?","Non. C'est un répertoire informatif indépendant, sans affiliation ni approbation de Superbuy."]],
 it:[["Cos'è uno spreadsheet Superbuy?","Un elenco indipendente di link a prodotti divisi per categoria. Aiuta la scoperta; la pagina prodotto attuale resta la fonte per prezzo, varianti e disponibilità."],["Cosa offre ufficialmente Superbuy in magazzino?","La guida descrive ispezione, foto di controllo e 90 giorni di deposito gratuito. Foto dettagliate e nuova ispezione sono servizi opzionali nella struttura costi attuale: chiedi una prova mirata quando serve."],["I prezzi mostrati sono definitivi?","No. Gli importi USD sono indicativi. Controlla variante attiva, consegna nazionale, eventuale commissione della piattaforma, servizi scelti e spedizione internazionale."],["Come viene calcolata la spedizione internazionale?","Il deposito dipende da destinazione, linea e dati stimati. Peso e dimensioni verificati fissano il totale; un'eccedenza viene restituita e un importo insufficiente può essere richiesto."],["L'acquisto standard è sempre gratuito?","Superbuy indica attualmente zero commissioni standard per Taobao, Tmall, JD.com e 1688. Usato, piattaforme non elencate o servizi speciali possono avere tariffe diverse."],["I 90 giorni sono anche il termine di reso?","No. Deposito e assistenza del venditore hanno scadenze separate. Dopo il periodo gratuito possono iniziare costi di deposito; il reso dipende dall'ordine e dallo stato after-sales disponibile."],["Ogni articolo può usare ogni linea?","No. Alcuni prodotti sono limitati a determinati metodi. Destinazione, classificazione e regole attuali del vettore contano; verifica gli articoli sensibili prima dell'acquisto."],["Questo è il sito ufficiale Superbuy?","No. È un indice informativo indipendente, non affiliato né approvato da Superbuy."]],
 nl:[["Wat is een Superbuy-spreadsheet?","Een onafhankelijke map met productlinks per categorie. Het versnelt zoeken; de actuele productpagina blijft leidend voor prijs, opties en voorraad."],["Wat biedt Superbuy officieel in het magazijn?","De gebruikersgids beschrijft inspectie, controlefoto's en 90 dagen gratis opslag. Detailfoto's en herinspectie staan als optionele diensten in het actuele kostenoverzicht; vraag gericht bewijs bij twijfel."],["Zijn de getoonde prijzen definitief?","Nee. USD-bedragen zijn indicatief. Controleer de exacte live variant, binnenlandse levering, eventuele platformkosten, gekozen diensten en internationale pakketkosten."],["Hoe worden internationale verzendkosten berekend?","Het voorschot hangt af van bestemming, route en geschatte gegevens. Geverifieerde afmetingen en gewicht bepalen het totaal; te veel betaald wordt teruggestort en een tekort kan worden geïnd."],["Is standaard inkopen altijd kosteloos?","Superbuy noemt standaard inkopen via Taobao, Tmall, JD.com en 1688 momenteel zonder inkoopkosten. Tweedehands, niet-genoemde platforms en speciale diensten kunnen andere tarieven hebben."],["Is 90 dagen opslag ook 90 dagen retourrecht?","Nee. Opslag en verkopersnazorg hebben aparte termijnen. Na de gratis periode kunnen opslagkosten beginnen; retour hangt af van de bestelling en de actieve after-salesstatus."],["Kan elk artikel via elke route worden verzonden?","Nee. Sommige artikelen zijn beperkt tot bepaalde methoden. Bestemming, classificatie en actuele vervoerdersregels bepalen de keuze; controleer gevoelige goederen vóór aankoop."],["Is dit de officiële Superbuy-website?","Nee. Dit is een onafhankelijke informatie- en productindex zonder band met of goedkeuring van Superbuy."]],
 ms:[["Apakah spreadsheet Superbuy?","Direktori bebas pautan produk mengikut kategori. Ia membantu penemuan; halaman produk semasa kekal sebagai sumber sebenar untuk harga, pilihan dan ketersediaan."],["Apakah yang Superbuy sediakan secara rasmi di gudang?","Panduan rasmi menerangkan pemeriksaan, foto semakan dan storan percuma 90 hari. Foto terperinci dan pemeriksaan semula disenaraikan sebagai perkhidmatan pilihan; minta bukti khusus apabila perlu."],["Adakah harga yang dipaparkan muktamad?","Tidak. Nilai USD ialah rujukan. Semak varian langsung, penghantaran China, yuran platform jika ada, perkhidmatan pilihan dan kos bungkusan antarabangsa."],["Bagaimanakah penghantaran antarabangsa dicaj?","Deposit bergantung pada destinasi, laluan dan data anggaran. Berat serta saiz yang disahkan menentukan jumlah; lebihan dipulangkan dan kekurangan mungkin perlu dibayar."],["Adakah pembelian biasa sentiasa tanpa yuran?","Superbuy kini menyatakan pembelian standard Taobao, Tmall, JD.com dan 1688 tanpa yuran pembelian. Platform terpakai, tidak tersenarai atau perkhidmatan khas boleh mempunyai caj lain."],["Adakah storan 90 hari juga tempoh pulangan?","Tidak. Storan dan selepas jualan penjual ialah tempoh berasingan. Caj storan boleh bermula selepas tempoh percuma; pulangan bergantung pada pesanan dan status selepas jualan semasa."],["Bolehkah semua item menggunakan semua laluan?","Tidak. Sesetengah item terhad kepada kaedah tertentu. Destinasi, klasifikasi dan peraturan pembawa semasa menentukan pilihan; semak barangan sensitif sebelum membeli."],["Adakah ini laman rasmi Superbuy?","Tidak. Ini direktori maklumat bebas dan tidak mempunyai hubungan atau pengesahan daripada Superbuy."]],
};

