type Body={dek:string;sections:[string,string][]};
const enBodies:Record<string,Body>={
"how-to-use-superbuy-spreadsheet":{dek:"A product spreadsheet saves time only when you use it as a shortlist, not as proof that every listing is current, suitable or good value. This workflow keeps discovery, verification, warehouse inspection and parcel planning separate.",sections:[
["1. Define the purchase before opening links","Start with a short written brief: product type, intended use, acceptable color, your actual measurements, maximum item budget and any non-negotiable detail. A spreadsheet can contain hundreds or thousands of links, so browsing without a brief turns comparison into collecting tabs. Search one category at a time. Save only products that satisfy the same need, then compare like with like. A low item price is not automatically the best choice if the listing is unclear, the seller offers no useful size information or the item is likely to create a bulky parcel. Treat every category label and recommendation as a discovery aid, not an endorsement. This is especially important because marketplace listings can be edited, removed or replaced after a spreadsheet entry is published. Your brief gives you a stable reference even when the listing changes."],
["2. Verify the live destination page","Open the current product page and check the title, main photographs, selected variant, available sizes, seller information and current price. Do not assume that a familiar thumbnail means the live page still sells the same version. Color names may be similar while photos differ; one product page can also combine several materials or price tiers. Read option labels carefully and take a screenshot or note of the version you intend to order. If the link is dead, redirects to an unrelated listing or no longer offers the desired option, return to the category instead of forcing the purchase. The spreadsheet is a route to a listing; the live listing is the operational source of truth. If essential details are absent, ask a shopping enquiry before paying rather than hoping the warehouse photos will answer everything later."],
["3. Keep product discovery separate from Superbuy ordering","Superbuy's official user guidance describes two common starting methods: paste a Taobao, Tmall or JD.com product link into the search bar, or search for an item through Superbuy's interface. The platform then captures information for many listings; where automatic capture does not work, the user may need to complete a manual shopping-agent order. Before submitting, match the product URL, option, quantity and remarks to your notes. Use remarks for specific, observable requirements, not broad requests such as “make sure it is perfect.” Precise requests—confirm a stated color code, include a particular accessory, or measure a defined point—are easier to act on. Pay attention to China domestic shipping because it belongs to the purchasing stage and is separate from later international delivery."],
["4. Track the complete cost path","Superbuy's current fee structure separates costs into the purchasing stage, the international shipping stage and optional value-added services. The listed product price is only one line. China domestic delivery may be added by the seller. Superbuy says ordinary purchasing from mainstream platforms such as Taobao, Tmall, JD.com and 1688 has no purchasing service fee, while other platforms or special services can follow different rules. Optional detailed photos, re-inspection, packaging and other services cost extra when selected. International shipping is paid later. Keep a simple record for each candidate: product price, domestic delivery, likely weight, bulky packaging, optional services and a shipping buffer. That record prevents a cheap item from looking inexpensive when it may add substantial parcel volume or require special handling."],
["5. Use the warehouse as a decision gate","According to Superbuy, an item is inspected after arrival, stored in the warehouse and shown in the user's warehouse area. Its official pages state that three standard QC photos are provided free and that items receive 90 days of free storage. Those photos are useful for visible comparison, but they are not a laboratory test, authentication guarantee or fit test. First verify that the photographed color, size and version match the order. Then inspect overall shape, symmetry, seams, printing, hardware and visible damage. Compare both items of a pair. If an important area is missing, request a specific detailed photo or re-inspection rather than an arbitrary extra image. The most useful request identifies the exact view or measurement needed and explains what decision it will support."],
["6. Decide early: keep, return or investigate","Do not let an uncertain item sit in the warehouse while seller after-sales windows close. If photos show a wrong option, obvious damage or a major mismatch, open an enquiry promptly and ask what return or exchange options remain. Superbuy's published terms describe return and exchange conditions, but eligibility can depend on the marketplace, seller, product type and timing. Customized goods, deposits, second-hand items and some 1688 orders may have different limits. Avoid writing a universal return deadline into your personal plan; check the live order's available after-sales action. If the issue might be caused by angle or lighting, request one targeted view before escalating. Keep order screenshots and messages so the problem can be explained with evidence rather than memory."],
["7. Build the parcel deliberately","Once several items are ready, select them in the warehouse and compare available delivery routes for the actual destination. Superbuy's guidance says users can consolidate different orders, choose recommended delivery methods and add services such as package removal, reinforcement or insurance. Consolidation can reduce repeated first-weight charges, but a larger parcel is not automatically cheaper or safer. Footwear boxes, thick outerwear and rigid packaging can increase dimensional weight. Fragile items may need protection even when removing packaging would reduce volume. Check route restrictions for batteries, liquids, powders, branded or other sensitive goods. A product being purchasable does not guarantee that every line can carry it. Use the platform's current route list and shipping calculator rather than an old rate quoted in a spreadsheet or article."],
["8. Keep a small audit trail","A good spreadsheet workflow ends with records. Save the live URL, ordered option, paid price, warehouse weight, important QC images, requests, selected shipping line and parcel number. Mark links as checked on a date instead of calling them permanently verified. Product availability and platform rules change, so dated notes are more honest and useful than an undated “best find” label. After delivery, compare the received item with the QC images and packaging choices. Note what increased cost, which photo angle was most useful and whether a route estimate was close to the final charge. That feedback improves the next parcel far more than adding another hundred unreviewed links. The goal is not to browse the largest possible sheet; it is to make fewer, clearer decisions with evidence at each stage."],
["9. Avoid the shortcuts that create expensive mistakes","Three shortcuts cause most preventable confusion. First, do not order from a thumbnail without opening the live listing; product options and prices can change. Second, do not treat a QC photograph as an endorsement of authenticity, comfort or durability. It is evidence of visible condition, not a universal quality certificate. Third, do not compare products using item price alone. A bulky low-cost item may add more freight than a compact, higher-priced alternative. Also resist copying another buyer's parcel decision without checking destination and route availability, because shipping lines and customs rules differ by country. A careful workflow may feel slower during the first order, but it moves uncertainty to the stage where it is cheapest to solve. The best spreadsheet user is not the person who opens the most links; it is the person who knows why each saved link, extra photo and packaging choice is necessary."],
]},
"superbuy-qc-photos-checklist":{dek:"Superbuy says it provides three free standard QC photos after warehouse arrival. Those images reduce uncertainty, but only if you inspect them in a repeatable order and understand what a warehouse photo cannot prove.",sections:[
["1. Start with the order, not quality","Before judging craftsmanship, confirm that the image shows the item you actually ordered. Compare the color, size, model, quantity and selected option with your saved order note. Check labels and packaging when they are visible, but remember that a label alone does not establish authenticity or material. Multi-option marketplace pages are a common source of mistakes because one thumbnail can represent several colors or versions. If a pair is involved, verify both pieces are present and correspond. If the order itself is wrong, a detailed discussion of stitching is secondary. Record the mismatch clearly and contact the order team while after-sales options may still be available."],
["2. Read the complete silhouette","Move from the largest visual information to the smallest. Look at the front, back and side views if available. For clothing, compare shoulder balance, collar shape, sleeve length, hem, panel alignment and whether the garment lies evenly. For shoes, compare the pair: toe shape, heel height, side panels, sole edges and left-right symmetry. For bags, inspect the overall structure, handles and hardware placement. Perspective can distort proportions, so avoid using a wide-angle image for precise measurements. The purpose of this stage is to find major shape or construction inconsistencies that a close-up might hide."],
["3. Inspect the high-risk details","Zoom into seams, embroidery, print placement, edges, fasteners, zippers, buttons, sole joins and any exposed surface that could show scratches or stains. Identify the details that matter for that product instead of applying the same checklist mechanically. A plain sweatshirt needs different attention from a shoe, electronic item or fragile accessory. Lighting can create false color shifts and reflections, so compare multiple images before concluding that a mark exists. If an area is shadowed or compressed by packaging, describe exactly which angle is missing. A useful request might say “photograph the outer right shoe in daylight-like lighting” or “measure the chest width from armpit to armpit while laid flat.”"],
["4. Use paid detail services selectively","Superbuy's published fee page currently lists optional services including detailed photos, re-inspection, measurements or product-specific checks, and various packaging choices. These are not mandatory. Buy an extra service only when it can answer a decision question. A random fourth photo adds little; a close-up of a suspected defect or a defined measurement can determine whether to keep the item. For electronics and appliances, Superbuy also lists a power-on inspection service, but a successful power-on photo is not a durability test. For apparel, a model try-on or measurement may provide context, yet body shape and sizing expectations still vary. Match the service to the risk instead of adding every available option."],
["5. Know the limits of warehouse inspection","An image can confirm visible appearance at one moment. It cannot reliably prove long-term durability, internal construction, exact material composition, waterproofing, battery health, fit on your body or authenticity. Superbuy's own terms note that some categories cannot receive professional inspection and that appearance may be the practical limit. Color can differ because of lighting, camera settings and display calibration. Sealed products may not be opened. Treat QC as evidence for visible mismatch, missing parts and obvious damage—not as a guarantee that every seller claim is true. For high-risk or regulated products, study the listing, seller terms and shipping restrictions before ordering rather than relying on warehouse photography as a rescue step."],
["6. Respond quickly when something is wrong","If the photos show the wrong item, wrong option, missing quantity, damage or a serious visible flaw, create an enquiry promptly. Explain one issue at a time and attach the relevant image. Ask whether a seller return, exchange or additional proof is possible. Eligibility depends on the order, seller and timing, so use the live after-sales controls rather than assuming every item has the same window. Do not approve an item merely because international shipping has not yet been purchased. Warehouse storage time and seller after-sales time are different clocks. The official 90-day free storage period is useful for consolidation, but it should not be interpreted as a 90-day return period."],
["7. Make packaging part of QC","Your last inspection decision should include the way the item will travel. Superbuy lists optional services such as package removal, reinforced packaging, bubble cushioning and insurance. Removing a shoe box can reduce volume but removes structural protection and may affect resale or collection value. Reinforcement can protect fragile goods but adds material and potentially weight. A good choice depends on the product, route and consequence of damage. Photograph or note the condition before parcel submission, then select packaging deliberately. When combining items, consider whether hard hardware, shoes or electronics could press against soft clothing. QC is not finished when the product looks acceptable; it ends when the parcel plan protects what you approved."],
["8. Save evidence for delivery","Keep the order page, QC photos, additional service results, parcel photos if available, declared contents and tracking number together. When the parcel arrives, inspect the outer box before discarding it and compare the product with warehouse images. If there is damage or a missing item, photograph the packaging, label and contents immediately. Superbuy's guidance points users to after-sales support from the parcel area, while carrier and insurance terms can affect compensation. A clear evidence set is more persuasive than a general complaint. Finally, update your own checklist: note which default angle failed, which extra image helped and which packaging decision mattered. This turns one shipment into better judgment for the next."],
["9. Build a category-specific checklist","A universal checklist is a starting point, not the finish. For shoes, record pair symmetry, toe shape, sole bonding, heel alignment, size label and insole length when available. For clothing, prioritize stated measurements, print or embroidery placement, seam condition, color and visible stains. For bags, inspect overall structure, handles, closures, hardware and interior accessories when shown. Electronics need the correct model and plug, visible damage, accessories and—where appropriate—an optional power-on check, while recognizing that a brief test does not prove battery health or long-term operation. Fragile goods need condition evidence and a packaging plan. Save one short template per category so each request is specific. This is more reliable than asking warehouse staff to “check everything,” because a broad request does not identify what matters to your purchase."],
["10. Use a simple approve-or-escalate rule","After inspection, place the item into one of three states. Approve when the ordered option matches, no significant visible issue appears and the packaging plan is suitable. Escalate when a specific missing view, measurement or ambiguous mark prevents a decision; request only the evidence needed to resolve it. Open after-sales when there is a clear wrong item, missing quantity, damage or material mismatch and the live order still offers an action. Do not leave the state undefined. Uncertainty that sits in storage does not improve by itself, and seller response windows may continue to run. This rule keeps emotional reactions out of the process: you are not trying to prove that an item is perfect. You are deciding whether the evidence is sufficient for the cost and risk of international shipment."],
]},
"superbuy-shipping-cost-explained":{dek:"The item price is only the first stage of a Superbuy order. A useful estimate separates China-side purchasing costs, optional warehouse services and the international parcel charge instead of treating one screenshot as the total.",sections:[
["1. Understand the two-stage payment path","Superbuy's current fee structure divides the journey into purchasing and international shipping. In the first stage, the user pays the marketplace product price and any China domestic delivery. The official fee page says ordinary purchasing from mainstream platforms such as Taobao, Tmall, JD.com and 1688 has no purchasing service fee, while second-hand, unlisted or specialist services can use separate charges. After the seller ships and the item reaches the warehouse, it can be inspected and stored. International delivery is a later transaction. This separation explains why a low product price on a spreadsheet cannot represent the delivered cost. Record each stage independently so currency conversion, optional services and freight do not disappear inside a vague total."],
["2. Estimate product-side costs honestly","Begin with the live price for the exact color, size and version, not the lowest promotional number shown on a multi-option listing. Add China domestic delivery if the seller charges it. Include only the optional services you are likely to use: a detailed photo, re-inspection, packaging change or other request. Superbuy publishes unit prices for many value-added services, but those prices can change, so check them at the time of ordering. Currency conversion and payment method costs may also change the amount paid in your home currency. A spreadsheet USD figure is useful for screening products, but it should be labeled approximate. The most reliable comparison keeps original CNY amounts and records the conversion date rather than pretending an old dollar value is exact."],
["3. Weight is not the only number","International lines commonly charge by actual weight or a volumetric calculation based on parcel dimensions. A light but large shoe box, padded jacket or rigid collectible can therefore cost more than its scale weight suggests. Superbuy's official process states that the international shipping deposit is estimated using the product's expected weight, chosen route and destination, while the final amount is based on the package size and weight verified by the logistics provider. This is why pre-warehouse estimates are planning values. When the item is stored, use the recorded weight and dimensions where available. Consider whether original packaging is essential and whether consolidation will reduce duplicated packaging or create a much larger carton."],
["4. Read a route beyond its headline price","Compare destination availability, prohibited or restricted categories, first-weight and additional-weight increments, expected delivery range, tracking, customs handling, insurance eligibility and compensation rules. The lowest estimate may exclude the product type or create a poor risk trade-off. Batteries, liquids, powders, food, cosmetics and other sensitive goods can have fewer available routes. Superbuy says its system presents recommended lines based on the shipment, but the user still needs to check current restrictions. International delivery is performed by third-party logistics providers, so customs, weather and carrier operations can affect the outcome. Do not turn a delivery range into a promised arrival date, especially when planning around travel or gifts."],
["5. Decide whether consolidation really saves money","Superbuy offers 90 days of free storage and lets users combine different warehouse orders into one parcel. Consolidation can save money when it avoids repeated first-weight charges and unnecessary outer cartons. It can also backfire if waiting causes a seller after-sales window to close, if the combined parcel becomes volumetrically large, or if mixed product types reduce route choices. Group items with compatible handling needs. Soft clothing can fill space, while boxes, fragile goods and sharp hardware may need separation or reinforcement. Compare one consolidated estimate with two smaller parcels when the value or risk is high. The cheapest mathematical option is not always the best operational choice if loss or damage would affect every item at once."],
["6. Choose packaging with a reason","Official Superbuy pages list optional package removal, reinforcement, bubble cushioning, insurance and other services. Removing retail boxes may reduce dimensions; reinforcement and cushioning may add weight or volume. Make the choice product by product. For ordinary clothing, reducing excess seller packaging may be sensible. For shoes, collectibles, glass or electronics, structural protection can matter more than a small freight saving. If moisture is the main concern, a sealing option may be relevant; if compression is the risk, cushioning or a stronger outer carton may help. Avoid treating every add-on as automatically necessary. Write the failure you are trying to prevent, then select the lightest service that addresses it."],
["7. Understand deposits, adjustments and customs","When a parcel is submitted, Superbuy collects an international shipping deposit based on estimated data. Its user guidance says the final charge follows the logistics provider's verified parcel size and weight, and a difference between the final fee and deposit is returned to the Superbuy account after shipment. This adjustment is normal; it is not proof that the calculator was wrong. Customs charges are separate and depend on destination law, declared information and customs assessment. No spreadsheet or article can promise that a parcel will avoid tax or inspection. Use truthful declarations and read current destination guidance. Budget a buffer rather than spending the full limit on products before the final parcel quote appears."],
["8. Use a repeatable calculation","For every planned parcel, create five lines: exact product and domestic delivery cost; optional warehouse services; estimated chargeable weight; current route estimate; and a contingency for conversion, customs or adjustment. Recalculate after warehouse data is available and again before parcel submission. Compare the final charge with the original plan after dispatch. Over time, your own records reveal which categories are bulky, which packaging choices add value and which routes suit your destination. That personal history is more useful than a universal claim that one route is always cheapest. Superbuy provides calculators and live route options; the spreadsheet's job is to help you reach a sensible shortlist, not to replace the parcel quotation."],
["9. Plan for route restrictions before buying","A marketplace seller may be able to send an item to the China warehouse even when international options are limited. This gap matters for products containing batteries, liquids, powders, magnets, food, cosmetics or other sensitive components. Before paying, check whether the intended destination currently has a compatible route and whether special handling changes the estimate. Superbuy's guidance notes that some items are restricted to certain delivery methods and that the system recommends eligible choices at parcel submission. Eligibility can still change with carrier policy, customs requirements and the exact product classification. If route availability is essential to the purchase, use a current shipping enquiry rather than relying on a screenshot from another user. An inexpensive item that cannot use the planned line may become costly to return, store or ship separately."],
["10. Compare value, not only the freight total","The goal is not always the lowest possible quote. A tracked route with clearer compensation terms may be worth more for a valuable parcel; a faster line may matter when storage or travel timing is tight; a smaller parcel may limit the impact of loss. Write the decision in plain language: what is being protected, what delay is acceptable and what additional cost is reasonable. Then compare the current routes against that brief. Avoid false precision—an estimate accurate to the cent can still change after packing, carrier verification or currency conversion. A sensible shipping budget includes a buffer and leaves room for destination tax where applicable. When the final parcel is delivered, calculate the landed cost per item only if that information helps future buying decisions; dividing freight equally can be misleading when one bulky item created most of the chargeable volume."],
]}
};

const compactBodies:Record<Exclude<Locale,"en">,Record<string,Body>>={
 de:{
  "how-to-use-superbuy-spreadsheet":{dek:"Eine Produkttabelle spart nur dann Zeit, wenn sie als Auswahlliste und nicht als Beweis für Aktualität oder Qualität genutzt wird.",sections:[["1. Bedarf zuerst festlegen","Notiere Kategorie, Einsatzzweck, Maße, Farbe, Artikelbudget und wichtige Details. Vergleiche nur Produkte für denselben Zweck. Kategorien und Empfehlungen helfen bei der Suche, sind aber keine Qualitätsgarantie."],["2. Aktuelle Produktseite prüfen","Kontrolliere Titel, Fotos, Variante, Größen, Verkäuferangaben und Live-Preis. Eine bekannte Vorschau kann später auf eine geänderte Anzeige führen. Fehlen wichtige Angaben, stelle vor der Zahlung eine konkrete Anfrage."],["3. Bestellung sauber übertragen","Superbuy beschreibt das Einfügen von Links aus Taobao, Tmall oder JD.com; wenn die automatische Erfassung scheitert, kann eine manuelle Bestellung nötig sein. Gleiche URL, Option, Menge und präzise Hinweise ab."],["4. Gesamtkosten aufzeichnen","Trenne Produktpreis, Inlandversand, mögliche Sondergebühr, Zusatzleistung und spätere internationale Fracht. Für Mainstream-Plattformen nennt Superbuy bei gewöhnlicher Beschaffung keine Einkaufsgebühr; Sonderfälle können abweichen."],["5. Lager als Entscheidungspunkt nutzen","Superbuy nennt Prüfung, drei kostenlose QC-Fotos und 90 Tage kostenlose Lagerung. Vergleiche zuerst Variante und Größe, danach Form, Symmetrie, Nähte, Druck und Schäden. Fordere bei Bedarf eine gezielte Ansicht an."],["6. Bei Problemen schnell reagieren","Falsche Option, Beschädigung oder deutliche Abweichung sofort melden. Rückgabe und Umtausch hängen von Verkäufer, Plattform, Produkttyp und Zeitpunkt ab. Lagerfrist und Verkäuferfrist sind nicht dasselbe."],["7. Paket bewusst planen","Vergleiche aktuelle Linien nach Ziel, Einschränkungen, Gewicht, Volumen, Tracking und Schutz. Konsolidierung kann sparen; sperrige Boxen oder gemischte Risikowaren können den Vorteil reduzieren."],["8. Nachweise behalten","Speichere Live-Link, Variante, Preis, QC-Bilder, Messungen, Linie und Paketnummer mit Datum. Prüfe nach Ankunft, welche Entscheidung hilfreich war, und verbessere damit die nächste Bestellung."],["9. Teure Abkürzungen vermeiden","Nie nur anhand eines Vorschaubildes bestellen, QC-Fotos nicht als Echtheits- oder Haltbarkeitsgarantie lesen und Produkte nicht nur nach Artikelpreis vergleichen. Ziel- und Linienregeln selbst prüfen. Gute Nutzer öffnen nicht die meisten Links, sondern begründen jeden gespeicherten Fund, jedes Zusatzfoto und jede Verpackungswahl."]]},
  "superbuy-qc-photos-checklist":{dek:"Drei kostenlose Standardfotos verringern Unsicherheit nur, wenn sie systematisch gelesen werden und ihre Grenzen klar sind.",sections:[["1. Bestellung bestätigen","Farbe, Größe, Modell, Menge und Option mit der Bestellung vergleichen, bevor die Verarbeitung bewertet wird."],["2. Gesamtform lesen","Vorder-, Rück- und Seitenansicht prüfen. Bei Paaren linkes und rechtes Teil vergleichen; Perspektive nicht mit einem Messwert verwechseln."],["3. Risikodetails vergrößern","Nähte, Druck, Stickerei, Sohlen, Reißverschlüsse, Beschläge, Flecken und Schäden produktbezogen prüfen."],["4. Zusatzfotos gezielt kaufen","Ein Detailfoto oder eine Nachprüfung ist sinnvoll, wenn es eine konkrete Frage beantwortet. Ein zufälliges Extra-Bild bringt wenig."],["5. Grenzen kennen","Fotos beweisen weder Haltbarkeit noch Material, Authentizität, Passform oder interne Funktion. Sie zeigen sichtbaren Zustand zu einem Zeitpunkt."],["6. Schnell handeln","Probleme einzeln benennen, Bildbeleg anhängen und verfügbare Rückgabe- oder Umtauschoptionen prüfen. 90 Tage Lagerung sind keine 90 Tage Rückgaberecht."],["7. Verpackung mitdenken","Entfernen von Kartons spart Volumen; Polsterung und Verstärkung schützen, können aber Gewicht erhöhen. Nach Risiko entscheiden."],["8. Beweise sichern","QC-Bilder, Paketdaten und Fotos bei Erhalt aufbewahren. Bei Schaden Verpackung, Etikett und Inhalt sofort dokumentieren."],["9. Kategoriebezogene Checklisten","Bei Schuhen Paar, Form, Sohlen und Länge prüfen; bei Kleidung Maße, Druck und Nähte; bei Taschen Struktur und Beschläge; bei Elektronik Modell, Zubehör und gegebenenfalls Einschaltprüfung. Eine präzise Liste ist besser als die pauschale Bitte, alles zu prüfen."],["10. Freigeben oder eskalieren","Freigeben, wenn Option und sichtbarer Zustand stimmen. Bei fehlender Ansicht gezielt nachfordern. Bei klar falscher Ware, Schaden oder Fehlmenge sofort After-Sales öffnen. Unklarheit nicht ohne Entscheidung im Lager liegen lassen."]]},
  "superbuy-shipping-cost-explained":{dek:"Der Artikelpreis ist nur die erste Stufe. Eine belastbare Schätzung trennt China-Kosten, Lagerleistungen und internationale Fracht.",sections:[["1. Zwei Zahlungsstufen","Zuerst fallen Produktpreis und möglicher Inlandversand an, später die internationale Lieferung. Für gewöhnliche Bestellungen auf Mainstream-Plattformen nennt Superbuy keine Einkaufsgebühr; Sonderdienste können kostenpflichtig sein."],["2. Artikelkosten ehrlich schätzen","Nutze den Preis der exakten Variante, addiere Inlandversand und nur benötigte Zusatzleistungen. USD-Werte bleiben wegen Kursen und Preisänderungen Richtwerte."],["3. Gewicht und Volumen","Leichte, sperrige Kartons können nach Volumengewicht teurer sein. Die Vorauszahlung basiert auf Schätzdaten; Maße und Gewicht des Dienstleisters bestimmen den Endpreis."],["4. Versandlinie vollständig lesen","Ziel, Einschränkungen, Gewichtsstufen, Tracking, Zeitraum, Versicherung und Entschädigung vergleichen. Der niedrigste Betrag ist nicht automatisch die passende Linie."],["5. Konsolidierung prüfen","Zusammenfassen kann wiederholte Grundgewichte sparen, aber Volumen, Risikomischung und Wartezeit erhöhen. Bei wertvollen Sendungen ein großes Paket mit zwei kleineren vergleichen."],["6. Verpackung begründen","Kartonentfernung reduziert Volumen; Verstärkung und Polsterung schützen, erhöhen aber Material. Nur Leistungen wählen, die ein konkretes Risiko lösen."],["7. Vorauszahlung und Zoll","Superbuy gleicht die Vorauszahlung nach verifiziertem Paketwert aus und schreibt Differenzen dem Guthaben gut. Zoll hängt vom Zielland ab und lässt sich nicht garantieren."],["8. Wiederholbar kalkulieren","Produkt/Inland, Lagerdienste, geschätztes abrechenbares Gewicht, Live-Linie und Puffer getrennt erfassen. Nach Einlagerung und vor Abgabe neu rechnen."],["9. Einschränkungen vor dem Kauf","Ein Artikel kann das China-Lager erreichen und international trotzdem nur wenige Linien haben. Batterien, Flüssigkeiten, Pulver oder sensible Waren vor Zahlung gegen aktuelle Ziel- und Linienregeln prüfen; bei Unsicherheit eine aktuelle Versandanfrage stellen."],["10. Wert statt nur Fracht vergleichen","Tracking, Entschädigung, akzeptable Laufzeit und Schadensfolge in die Entscheidung einbeziehen. Ein kleineres oder besser geschütztes Paket kann trotz höherem Preis sinnvoller sein. Schätzungen bleiben trotz genauer Anzeige veränderlich, daher einen Puffer einplanen."]]},
 },
 fr:{
  "how-to-use-superbuy-spreadsheet":{dek:"Un tableur n'est utile que comme présélection : il ne prouve ni l'actualité d'une annonce, ni sa qualité, ni son coût livré.",sections:[["1. Définir le besoin","Noter catégorie, usage, mesures, couleur, budget produit et détails essentiels. Comparer des produits répondant au même besoin ; une catégorie n'est pas une recommandation."],["2. Vérifier la page active","Contrôler titre, photos, variante, tailles, vendeur et prix actuel. Une vignette familière peut mener à une annonce modifiée. Poser une question précise avant paiement si une donnée essentielle manque."],["3. Transmettre correctement la commande","Superbuy décrit le collage de liens Taobao, Tmall ou JD.com et la saisie manuelle lorsque la capture échoue. Vérifier URL, option, quantité et remarques observables."],["4. Suivre le coût complet","Séparer prix, transport chinois, éventuels frais particuliers, services optionnels et futur envoi international. Superbuy annonce l'achat standard sans frais sur plusieurs grandes plateformes, avec des exceptions."],["5. Utiliser l'entrepôt comme filtre","Superbuy annonce inspection, trois photos QC gratuites et 90 jours de stockage gratuit. Vérifier option, forme, symétrie, coutures, impressions et dommages ; demander une vue ciblée si nécessaire."],["6. Réagir vite aux problèmes","Signaler immédiatement mauvaise option, dommage ou écart majeur. Retour et échange dépendent du vendeur, du produit et du délai ; stockage et service après-vente suivent deux horloges différentes."],["7. Construire le colis","Comparer les lignes actuelles selon destination, restrictions, poids, volume, suivi et protection. La consolidation peut économiser, mais les boîtes volumineuses ou les risques mixtes peuvent annuler le gain."],["8. Garder une trace","Conserver lien, variante, prix, photos QC, mesures, ligne et numéro de colis avec une date. Après livraison, noter ce qui a réellement aidé la décision."],["9. Éviter les raccourcis coûteux","Ne pas commander depuis une vignette, prendre une photo QC pour une preuve d'authenticité ou comparer uniquement le prix produit. Vérifier soi-même destination et ligne. Chaque lien, photo supplémentaire et choix d'emballage doit répondre à une raison claire."]]},
  "superbuy-qc-photos-checklist":{dek:"Les trois photos standard gratuites réduisent l'incertitude si elles sont examinées dans un ordre constant et sans leur demander plus qu'elles ne peuvent prouver.",sections:[["1. Confirmer la commande","Comparer couleur, taille, modèle, quantité et option avant d'évaluer la fabrication."],["2. Lire la forme générale","Observer face, dos et côtés ; comparer les deux éléments d'une paire et ne pas confondre perspective et mesure."],["3. Examiner les détails à risque","Contrôler coutures, broderie, impressions, semelles, fermetures, pièces métalliques, taches et dommages selon le produit."],["4. Acheter un complément ciblé","Une photo détaillée ou une nouvelle inspection est utile si elle répond à une question précise. Une image supplémentaire aléatoire aide peu."],["5. Connaître les limites","Les photos ne prouvent pas durabilité, matière, authenticité, taille portée ou fonctionnement interne. Elles montrent un état visible à un instant."],["6. Agir rapidement","Décrire chaque problème, joindre l'image et vérifier les options de retour ou d'échange. Les 90 jours de stockage ne constituent pas un délai de retour."],["7. Inclure l'emballage","Retirer une boîte réduit le volume ; renfort et protection amortissent mais peuvent ajouter du poids. Choisir selon le risque réel."],["8. Conserver les preuves","Garder photos QC et données du colis. À la réception, documenter immédiatement carton, étiquette et contenu en cas de dommage."],["9. Adapter la liste à la catégorie","Chaussures : paire, forme, semelles et longueur ; vêtements : mesures, impression et coutures ; sacs : structure et pièces ; électronique : modèle, accessoires et test d'allumage éventuel. Une demande précise vaut mieux que « tout vérifier »."] ,["10. Approuver ou escalader","Approuver si option et état visible concordent. Demander la preuve ciblée si une vue manque. Ouvrir l'après-vente pour mauvais article, dommage ou quantité manquante. Ne pas laisser l'incertitude sans décision."]]},
  "superbuy-shipping-cost-explained":{dek:"Le prix produit n'est que la première étape. Une estimation utile sépare achats en Chine, services d'entrepôt et transport international.",sections:[["1. Deux étapes de paiement","Le prix produit et l'éventuelle livraison chinoise viennent d'abord, puis le transport international. Superbuy annonce l'achat standard sans frais sur plusieurs grandes plateformes ; les services particuliers diffèrent."],["2. Estimer le produit honnêtement","Prendre le prix de la variante exacte, ajouter livraison locale et services réellement nécessaires. Les montants USD restent indicatifs à cause des taux et changements."],["3. Poids et volume","Un carton léger mais volumineux peut être facturé au poids volumétrique. L'acompte repose sur une estimation ; poids et dimensions vérifiés fixent le total."],["4. Lire toute la ligne","Comparer destination, restrictions, paliers de poids, suivi, délai, assurance et compensation. Le prix le plus bas n'est pas toujours compatible."],["5. Tester la consolidation","Regrouper peut éviter plusieurs premiers poids, mais augmenter volume, délai ou risque commun. Pour un colis de valeur, comparer un grand envoi à deux petits."],["6. Justifier l'emballage","Retirer une boîte réduit le volume ; renfort et calage protègent mais ajoutent de la matière. Choisir le service le plus léger qui traite le risque."],["7. Acompte et douane","Superbuy ajuste après les données vérifiées et crédite l'écart au solde. La douane dépend du pays et aucune page ne peut garantir l'absence de taxe."],["8. Calcul répétable","Séparer produit/local, services, poids facturable estimé, ligne actuelle et marge. Recalculer après entrée en stock et avant soumission."],["9. Restrictions avant l'achat","Un produit peut atteindre l'entrepôt chinois tout en ayant peu de lignes internationales. Vérifier batteries, liquides, poudres et articles sensibles selon destination ; demander une solution actuelle si le doute conditionne l'achat."],["10. Comparer la valeur, pas seulement le fret","Inclure suivi, compensation, délai acceptable et conséquence d'un dommage. Un petit colis mieux protégé peut valoir le surcoût. Garder une marge car estimation, dimensions et conversion peuvent encore évoluer."]]},
 },
 it:{
  "how-to-use-superbuy-spreadsheet":{dek:"Uno spreadsheet fa risparmiare tempo solo se viene usato come selezione, non come prova che ogni inserzione sia attuale, conveniente o adatta.",sections:[["1. Definisci il bisogno","Annota categoria, uso, misure, colore, budget del prodotto e dettagli essenziali. Confronta articoli con lo stesso scopo; una categoria non è un'approvazione."],["2. Controlla la pagina attuale","Verifica titolo, foto, variante, taglie, venditore e prezzo live. Una miniatura nota può portare a un'inserzione modificata. Chiedi chiarimenti prima del pagamento."],["3. Trasferisci bene l'ordine","Superbuy descrive l'inserimento di link Taobao, Tmall o JD.com e l'ordine manuale quando la cattura non riesce. Controlla URL, opzione, quantità e note precise."],["4. Registra il costo completo","Separa prezzo, spedizione cinese, eventuali servizi speciali, extra di magazzino e futura spedizione internazionale. Superbuy indica acquisto ordinario senza commissione su piattaforme principali, con eccezioni."],["5. Usa il magazzino come filtro","Superbuy indica ispezione, tre foto QC gratuite e 90 giorni di deposito gratuito. Controlla opzione, forma, simmetria, cuciture, stampe e danni; chiedi una vista mirata."],["6. Reagisci subito ai problemi","Segnala opzione errata, danno o differenza importante. Reso e cambio dipendono da venditore, prodotto e tempo; deposito e assistenza hanno scadenze diverse."],["7. Progetta il pacco","Confronta linee attuali per destinazione, restrizioni, peso, volume, tracking e protezione. Consolidare può aiutare, ma scatole voluminose o rischi misti possono annullare il vantaggio."],["8. Conserva le prove","Salva link, variante, prezzo, foto QC, misure, linea e numero pacco con data. Dopo la consegna annota quali decisioni hanno funzionato."]]},
  "superbuy-qc-photos-checklist":{dek:"Le tre foto standard gratuite riducono l'incertezza solo se lette in modo sistematico e rispettandone i limiti.",sections:[["1. Conferma l'ordine","Confronta colore, taglia, modello, quantità e opzione prima di giudicare la qualità."],["2. Leggi la forma generale","Guarda fronte, retro e lati; confronta entrambi gli elementi di una coppia e non usare la prospettiva come misura."],["3. Controlla i punti a rischio","Esamina cuciture, ricami, stampe, suole, chiusure, hardware, macchie e danni secondo il prodotto."],["4. Compra extra mirati","Una foto dettagliata o un nuovo controllo serve se risponde a una domanda precisa; una foto casuale in più aggiunge poco."],["5. Conosci i limiti","Le immagini non provano durata, materiale, autenticità, vestibilità o funzionamento interno. Mostrano condizioni visibili in un momento."],["6. Agisci rapidamente","Descrivi ogni problema, allega la foto e verifica reso o cambio disponibili. I 90 giorni di deposito non sono 90 giorni per restituire."],["7. Includi l'imballaggio","Rimuovere scatole riduce volume; rinforzo e imbottitura proteggono ma possono aggiungere peso. Decidi in base al rischio."],["8. Salva le prove","Conserva foto QC e dati del pacco. Alla consegna fotografa subito scatola, etichetta e contenuto se c'è un danno."]]},
  "superbuy-shipping-cost-explained":{dek:"Il prezzo dell'articolo è solo il primo stadio. Una stima affidabile separa costi in Cina, servizi di magazzino e spedizione internazionale.",sections:[["1. Due fasi di pagamento","Prima si pagano prodotto e consegna cinese, poi la spedizione internazionale. Superbuy indica nessuna commissione d'acquisto ordinaria su varie piattaforme principali; i servizi speciali differiscono."],["2. Stima onesta del prodotto","Usa il prezzo della variante esatta, aggiungi consegna locale e solo gli extra necessari. I valori USD restano indicativi per cambio e aggiornamenti."],["3. Peso e volume","Una scatola leggera ma grande può essere tariffata sul peso volumetrico. Il deposito usa una stima; misure e peso verificati definiscono il totale."],["4. Leggi tutta la linea","Confronta destinazione, limiti, scaglioni di peso, tracking, tempi, assicurazione e compensazione. Il prezzo più basso può non essere compatibile."],["5. Valuta il consolidamento","Unire può evitare più primi pesi, ma aumentare volume, attesa o rischio comune. Per articoli di valore confronta un pacco grande con due piccoli."],["6. Motiva l'imballaggio","Togliere una scatola riduce volume; rinforzo e imbottitura proteggono ma aggiungono materiale. Scegli solo ciò che risolve un rischio."],["7. Deposito e dogana","Superbuy regola il costo dopo i dati verificati e accredita la differenza al saldo. La dogana dipende dal paese e non può essere garantita."],["8. Calcolo ripetibile","Separa prodotto/locale, servizi, peso fatturabile stimato, linea live e margine. Ricalcola dopo il magazzino e prima dell'invio."]]},
 },
 nl:{
  "how-to-use-superbuy-spreadsheet":{dek:"Een spreadsheet bespaart alleen tijd als shortlist, niet als bewijs dat elke aanbieding actueel, geschikt of voordelig is.",sections:[["1. Bepaal eerst de behoefte","Noteer categorie, gebruik, maten, kleur, productbudget en essentiële details. Vergelijk producten voor hetzelfde doel; een categorie is geen aanbeveling."],["2. Controleer de live pagina","Bekijk titel, foto's, variant, maten, verkoper en actuele prijs. Een bekende thumbnail kan naar een gewijzigde advertentie leiden. Vraag ontbrekende informatie vóór betaling."],["3. Zet de bestelling correct over","Superbuy beschrijft het plakken van Taobao-, Tmall- of JD.com-links en handmatige invoer wanneer uitlezen niet lukt. Controleer URL, optie, aantal en concrete opmerkingen."],["4. Volg het hele kostenpad","Scheid productprijs, China-verzending, eventuele bijzondere kosten, magazijnextra's en latere internationale vracht. Superbuy noemt standaard inkopen zonder servicekosten op grote platforms, met uitzonderingen."],["5. Gebruik het magazijn als beslispoort","Superbuy noemt inspectie, drie gratis QC-foto's en 90 dagen gratis opslag. Controleer optie, vorm, symmetrie, naden, prints en schade; vraag gericht extra beeld."],["6. Reageer snel op problemen","Meld verkeerde optie, schade of groot verschil meteen. Retour en ruil hangen af van verkoper, product en timing; opslagtermijn is niet hetzelfde als retourtermijn."],["7. Bouw het pakket bewust","Vergelijk actuele routes op bestemming, beperkingen, gewicht, volume, tracking en bescherming. Consolidatie kan besparen, maar grote dozen of gemengde risico's kunnen dat tenietdoen."],["8. Bewaar bewijs","Bewaar link, variant, prijs, QC-foto's, metingen, route en pakketnummer met datum. Noteer na ontvangst welke beslissing echt hielp."]]},
  "superbuy-qc-photos-checklist":{dek:"Drie gratis standaardfoto's verminderen onzekerheid alleen met een vaste controlevolgorde en realistische verwachtingen.",sections:[["1. Bevestig de bestelling","Vergelijk kleur, maat, model, aantal en optie voordat je afwerking beoordeelt."],["2. Lees de totale vorm","Bekijk voor-, achter- en zijkant; vergelijk beide delen van een paar en gebruik perspectief niet als exacte maat."],["3. Controleer risicodetails","Bekijk naden, borduurwerk, prints, zolen, sluitingen, hardware, vlekken en schade per producttype."],["4. Koop gerichte extra's","Een detailfoto of herinspectie helpt als die één concrete vraag beantwoordt. Een willekeurige extra foto voegt weinig toe."],["5. Ken de grenzen","Foto's bewijzen geen duurzaamheid, materiaal, echtheid, pasvorm of interne werking. Ze tonen zichtbare staat op één moment."],["6. Handel snel","Beschrijf elk probleem, voeg beeld toe en bekijk beschikbare retour- of ruilopties. 90 dagen opslag is geen retourperiode."],["7. Neem verpakking mee","Dozen verwijderen verlaagt volume; versteviging en demping beschermen maar voegen materiaal toe. Kies op basis van risico."],["8. Bewaar bewijs","Bewaar QC-beelden en pakketgegevens. Fotografeer bij schade direct doos, label en inhoud."]]},
  "superbuy-shipping-cost-explained":{dek:"De productprijs is slechts fase één. Een goede raming scheidt China-kosten, magazijndiensten en internationale vracht.",sections:[["1. Twee betaalfasen","Eerst komen product en binnenlandse levering, daarna internationale verzending. Superbuy noemt standaard inkopen zonder servicekosten op verschillende grote platforms; bijzondere diensten wijken af."],["2. Eerlijke productraming","Gebruik de prijs van de exacte variant, tel lokale levering en alleen nodige extra's op. USD-bedragen blijven indicatief door koers en wijzigingen."],["3. Gewicht en volume","Een lichte grote doos kan op volumegewicht worden afgerekend. Het voorschot gebruikt een schatting; geverifieerde afmetingen en gewicht bepalen het totaal."],["4. Lees de hele route","Vergelijk bestemming, beperkingen, gewichtsstappen, tracking, tijd, verzekering en vergoeding. De laagste prijs hoeft niet geschikt te zijn."],["5. Test consolidatie","Samenvoegen kan meerdere starttarieven vermijden, maar volume, wachten en gedeeld risico verhogen. Vergelijk bij waardevolle spullen één groot met twee kleine pakketten."],["6. Motiveer verpakking","Een doos verwijderen bespaart volume; versteviging en demping beschermen maar voegen materiaal toe. Kies alleen wat een concreet risico oplost."],["7. Voorschot en douane","Superbuy past na verificatie aan en stort verschil op het saldo. Douane hangt af van het land en kan niet worden gegarandeerd."],["8. Herhaalbare berekening","Scheid product/lokaal, diensten, geschat factureerbaar gewicht, live route en buffer. Bereken opnieuw na opslag en vóór indienen."]]},
 },
 ms:{
  "how-to-use-superbuy-spreadsheet":{dek:"Spreadsheet menjimatkan masa hanya apabila digunakan sebagai senarai pendek, bukannya bukti bahawa setiap penyenaraian masih semasa, sesuai atau bernilai.",sections:[["1. Tetapkan keperluan dahulu","Catat kategori, kegunaan, ukuran, warna, bajet produk dan butiran penting. Bandingkan produk untuk tujuan yang sama; kategori bukan pengesahan kualiti."],["2. Sahkan halaman langsung","Semak tajuk, foto, varian, saiz, penjual dan harga semasa. Imej biasa boleh menuju ke penyenaraian yang telah berubah. Tanya soalan khusus sebelum membayar."],["3. Pindahkan pesanan dengan tepat","Superbuy menerangkan tampalan pautan Taobao, Tmall atau JD.com dan pesanan manual apabila tangkapan gagal. Padankan URL, pilihan, kuantiti dan catatan yang boleh diperiksa."],["4. Rekod semua kos","Asingkan harga produk, penghantaran China, caj khas, perkhidmatan gudang dan penghantaran antarabangsa. Superbuy menyatakan pembelian biasa tanpa yuran pada platform utama, dengan pengecualian."],["5. Jadikan gudang titik keputusan","Superbuy menyatakan pemeriksaan, tiga foto QC percuma dan storan percuma 90 hari. Semak pilihan, bentuk, simetri, jahitan, cetakan dan kerosakan; minta pandangan khusus."],["6. Bertindak cepat jika bermasalah","Laporkan pilihan salah, kerosakan atau perbezaan besar segera. Pulangan bergantung pada penjual, produk dan masa; tempoh storan bukan tempoh pemulangan."],["7. Rancang bungkusan","Bandingkan laluan semasa mengikut destinasi, sekatan, berat, isipadu, penjejakan dan perlindungan. Penyatuan boleh menjimatkan tetapi kotak besar atau risiko bercampur boleh mengurangkan manfaat."],["8. Simpan bukti","Simpan pautan, varian, harga, foto QC, ukuran, laluan dan nombor bungkusan dengan tarikh. Selepas tiba, catat keputusan yang paling membantu."]]},
  "superbuy-qc-photos-checklist":{dek:"Tiga foto standard percuma mengurangkan ketidakpastian hanya jika diperiksa mengikut urutan dan hadnya difahami.",sections:[["1. Sahkan pesanan","Bandingkan warna, saiz, model, kuantiti dan pilihan sebelum menilai mutu."],["2. Baca bentuk keseluruhan","Lihat hadapan, belakang dan sisi; bandingkan kedua-dua bahagian pasangan dan jangan anggap perspektif sebagai ukuran."],["3. Periksa butiran berisiko","Semak jahitan, sulaman, cetakan, tapak, zip, perkakasan, kotoran dan kerosakan mengikut jenis produk."],["4. Beli tambahan yang tepat","Foto terperinci atau pemeriksaan semula berguna jika menjawab satu soalan khusus. Foto rawak tambahan tidak banyak membantu."],["5. Fahami had","Foto tidak membuktikan ketahanan, bahan, ketulenan, kesesuaian badan atau fungsi dalaman. Ia menunjukkan keadaan nampak pada satu masa."],["6. Bertindak segera","Huraikan setiap masalah, lampirkan imej dan semak pilihan pulangan atau pertukaran. Storan 90 hari bukan tempoh pulangan."],["7. Sertakan pembungkusan","Membuang kotak mengurangkan isipadu; pengukuhan dan kusyen melindungi tetapi menambah bahan. Pilih mengikut risiko."],["8. Simpan bukti","Simpan foto QC dan data bungkusan. Jika rosak, rakam kotak, label dan kandungan sebaik diterima."]]},
  "superbuy-shipping-cost-explained":{dek:"Harga produk hanyalah peringkat pertama. Anggaran yang baik mengasingkan kos China, perkhidmatan gudang dan penghantaran antarabangsa.",sections:[["1. Dua peringkat bayaran","Produk dan penghantaran domestik dibayar dahulu, kemudian penghantaran antarabangsa. Superbuy menyatakan pembelian biasa tanpa yuran pada beberapa platform utama; perkhidmatan khas berbeza."],["2. Anggaran produk yang jujur","Gunakan harga varian tepat, tambah penghantaran tempatan dan hanya perkhidmatan perlu. Nilai USD kekal sebagai rujukan kerana kadar tukaran dan perubahan."],["3. Berat dan isipadu","Kotak ringan tetapi besar mungkin dicaj mengikut berat isipadu. Deposit menggunakan anggaran; ukuran dan berat yang disahkan menentukan jumlah."],["4. Baca seluruh laluan","Bandingkan destinasi, sekatan, unit berat, penjejakan, masa, insurans dan pampasan. Harga terendah mungkin tidak sesuai."],["5. Uji penyatuan","Menggabungkan boleh menjimatkan caj awal tetapi meningkatkan isipadu, masa menunggu dan risiko bersama. Untuk nilai tinggi, bandingkan satu bungkusan besar dengan dua kecil."],["6. Beri sebab untuk pembungkusan","Membuang kotak menjimatkan ruang; pengukuhan dan kusyen melindungi tetapi menambah bahan. Pilih hanya untuk risiko khusus."],["7. Deposit dan kastam","Superbuy melaras selepas data disahkan dan mengkredit perbezaan ke baki. Kastam bergantung pada negara dan tidak boleh dijamin."],["8. Kiraan berulang","Asingkan produk/tempatan, perkhidmatan, anggaran berat dicaj, laluan langsung dan penampan. Kira semula selepas masuk gudang dan sebelum hantar."]]},
 }
};

const extraSections:Partial<Record<Exclude<Locale,"en">,Record<string,[string,string][]>>>={
 it:{
  "how-to-use-superbuy-spreadsheet":[["9. Evita le scorciatoie costose","Non ordinare da una miniatura, non leggere le foto QC come prova di autenticità o durata e non confrontare solo il prezzo dell'articolo. Verifica destinazione e linea. Ogni link, foto extra e scelta di imballaggio deve avere uno scopo chiaro."]],
  "superbuy-qc-photos-checklist":[["9. Adatta la checklist alla categoria","Scarpe: coppia, forma, suole e lunghezza; abbigliamento: misure, stampa e cuciture; borse: struttura e hardware; elettronica: modello, accessori ed eventuale accensione. Una richiesta precisa è migliore di “controlla tutto”."],["10. Approva o chiedi intervento","Approva se opzione e stato visibile corrispondono. Chiedi una prova mirata se manca una vista. Apri l'assistenza per articolo errato, danno o quantità mancante. Non lasciare l'incertezza senza decisione."]],
  "superbuy-shipping-cost-explained":[["9. Verifica le restrizioni prima dell'acquisto","Un prodotto può arrivare al magazzino cinese ma avere poche linee internazionali. Controlla batterie, liquidi, polveri e articoli sensibili per la destinazione e chiedi una soluzione attuale se influenza l'acquisto."],["10. Confronta il valore, non solo il nolo","Considera tracking, compensazione, tempo accettabile e conseguenza di un danno. Un pacco piccolo e protetto può valere di più. Mantieni un margine perché stima, dimensioni e conversione possono cambiare."]],
 },
 nl:{
  "how-to-use-superbuy-spreadsheet":[["9. Vermijd dure shortcuts","Bestel niet vanaf een thumbnail, zie QC-foto's niet als bewijs van echtheid of levensduur en vergelijk niet alleen de artikelprijs. Controleer bestemming en route. Elke opgeslagen link, extra foto en verpakking moet een duidelijke reden hebben."]],
  "superbuy-qc-photos-checklist":[["9. Maak de checklist categoriespecifiek","Schoenen: paar, vorm, zolen en lengte; kleding: maten, print en naden; tassen: structuur en hardware; elektronica: model, accessoires en eventueel inschakelen. Een precieze vraag werkt beter dan ‘controleer alles’."],["10. Goedkeuren of escaleren","Keur goed als optie en zichtbare staat kloppen. Vraag gericht bewijs als een beeld ontbreekt. Open nazorg bij een verkeerd artikel, schade of ontbrekend aantal. Laat onzekerheid niet zonder besluit liggen."]],
  "superbuy-shipping-cost-explained":[["9. Controleer beperkingen vóór aankoop","Een artikel kan het China-magazijn bereiken maar weinig internationale routes hebben. Controleer batterijen, vloeistoffen, poeders en gevoelige goederen per bestemming; vraag actuele verzendinformatie als dit de aankoop bepaalt."],["10. Vergelijk waarde, niet alleen vracht","Neem tracking, vergoeding, aanvaardbare tijd en gevolgen van schade mee. Een kleiner beschermd pakket kan de meerprijs waard zijn. Houd een buffer omdat schatting, maten en conversie kunnen wijzigen."]],
 },
 ms:{
  "how-to-use-superbuy-spreadsheet":[["9. Elakkan jalan pintas yang mahal","Jangan pesan daripada imej kecil, anggap foto QC sebagai bukti ketulenan atau ketahanan, atau banding harga produk sahaja. Semak destinasi dan laluan. Setiap pautan, foto tambahan dan pilihan pembungkusan mesti mempunyai tujuan jelas."]],
  "superbuy-qc-photos-checklist":[["9. Sesuaikan senarai mengikut kategori","Kasut: pasangan, bentuk, tapak dan panjang; pakaian: ukuran, cetakan dan jahitan; beg: struktur dan perkakasan; elektronik: model, aksesori dan ujian kuasa jika perlu. Permintaan khusus lebih baik daripada “semak semuanya”."],["10. Luluskan atau eskalasi","Luluskan jika pilihan dan keadaan nampak sepadan. Minta bukti khusus jika pandangan tiada. Buka selepas jualan untuk produk salah, rosak atau kuantiti hilang. Jangan biarkan ketidakpastian tanpa keputusan."]],
  "superbuy-shipping-cost-explained":[["9. Semak sekatan sebelum membeli","Produk boleh tiba di gudang China tetapi mempunyai sedikit laluan antarabangsa. Semak bateri, cecair, serbuk dan produk sensitif untuk destinasi; minta maklumat semasa jika ia menentukan pembelian."],["10. Bandingkan nilai, bukan tambang sahaja","Ambil kira penjejakan, pampasan, masa boleh diterima dan kesan kerosakan. Bungkusan kecil yang dilindungi mungkin berbaloi. Sediakan penampan kerana anggaran, ukuran dan tukaran boleh berubah."]],
 }
};

export function articleBody(locale:Locale,slug:string):Body{
 if(locale==="en")return enBodies[slug];
 const base=compactBodies[locale][slug];
 const target=enBodies[slug].sections.length;
 const additions=(extraSections[locale]?.[slug]||[]).slice(0,Math.max(0,target-base.sections.length));
 return {...base,sections:[...base.sections,...additions]};
}

